#' Lasso Initial State
#' 
#' Generate initial Markov chain state with Lasso.
#' 
#' @param X Design matrix of traning data; 
#' rows should be for the cases, and columns for different features.
#' 
#' @param y Vector of class labels in training or test data set. 
#' Must be coded as non-negative integers, e.g., 1,2,\ldots,C for C classes.
#' 
#' @param lambda A user supplied lambda sequence for \code{glmnet} cross-validation.
#' \code{NULL} by default, and it will be generated by \code{glmnet}.
#' 
#' @param alpha The elasticnet mixing parameter for \code{glmnet}.
#' @param verbose Logical; report the cross-validated lambda when \code{TRUE}.
#' @param rank_fn,k Deprecated initializer screening arguments. Use a separate
#' ranking helper and pass selected indices to \code{htlr(..., fsel = ...)}
#' to screen the final model, or wrap subset coefficients in \code{htlr_init()}
#' to initialize only a subset. Legacy \code{k} screening now returns all input
#' feature rows, with omitted coefficients set to zero.
#' 
#' @return A numeric matrix with \code{ncol(X) + 1} rows, intercept first,
#' followed by every input feature in its original order, and one column per
#' non-reference class. Feature row names are retained when \code{X} has column
#' names; class columns use \code{levels(factor(y))[-1]}.
#' @details This helper generates coefficients on the supplied predictor scale;
#' it does not select the final HTLR model features. Screening is a separate
#' operation using \code{order_ftest()}, \code{order_kruskal()}, or
#' \code{order_plain()}. Pass a subset of the ranking to \code{fsel} to choose
#' final fitted features. To initialize fewer features while fitting all of
#' them, compute coefficients on \code{X[, selected, drop = FALSE]} and wrap
#' the result in \code{htlr_init(deltas, features = selected)}. When using
#' index metadata, remove coefficient row names first with
#' \code{rownames(deltas) <- NULL}, or use feature-name metadata instead.
#' 
#' @references Jerome Friedman, Trevor Hastie, Robert Tibshirani (2010).
#' Regularization Paths for Generalized Linear Models via Coordinate
#' Descent. \emph{Journal of Statistical Software}, 33(1), 1-22.  
#'
#' @importFrom glmnet glmnet cv.glmnet 
#'
#' @export
#' 
#' @keywords internal
#' 
#' @seealso \code{\link{bcbcsf_deltas}}
lasso_deltas <- function(X, y, lambda = NULL, verbose = FALSE, alpha = 1, rank_fn = order_plain, k = ncol(X))
{
  if (!missing(rank_fn) || !missing(k))
    warning("'rank_fn' and 'k' are deprecated in lasso_deltas(); rank features separately and use 'fsel' for final screening or htlr_init() for subset initialization. All input feature rows are returned, with zeros for omitted initial coefficients.",
            call. = FALSE)
  if (!is.numeric(k) || is.complex(k) || length(k) != 1L ||
      !is.finite(k) || k != floor(k) || k < 1 || k > ncol(X))
    stop("'k' must be a positive integer no larger than ncol(X).", call. = FALSE)
  original_names <- colnames(X)
  p <- ncol(X)
  fsel <- seq_len(p)
  if (k < p)
  {
    ranking <- resolve_fsel(rank_fn(X, y), X)
    if (length(ranking) != p)
      stop("'rank_fn' must rank every input feature exactly once.", call. = FALSE)
    fsel <- ranking[seq_len(k)]
    X <- X[, fsel, drop = FALSE]
  }
  
  if (is.null(lambda)) # pre.legacy == TRUE
  {
    lasso.fit <- cv.glmnet(x = X, y = y, alpha = alpha, nlambda = 500, family = "multinomial")
  }
  else
  {
    lasso.fit <- cv.glmnet(x = X, y = y, alpha = alpha, lambda = lambda, 
                           family = "multinomial", nfolds = 5)  
  }
  
  if (verbose)
    message("The best lambda chosen by CV: ", lasso.fit$lambda.min ,"\n")
  
  betas <- coef(lasso.fit, s = "lambda.min")
  mbetas <- as.matrix(Reduce(cbind, betas))
  deltas <- mbetas[, -1, drop = FALSE] - mbetas[, 1]
  # Coefficients always refer to all input columns, regardless of legacy screening.
  full_deltas <- matrix(0, p + 1L, ncol(deltas))
  full_deltas[c(1L, fsel + 1L), ] <- deltas
  if (!is.null(original_names))
    rownames(full_deltas) <- c("(Intercept)", original_names)
  colnames(full_deltas) <- levels(factor(y))[-1]
  return (full_deltas)
}

